"use client";

import { useLayoutEffect, useRef, useState } from "react";
import Image from "next/image";
import gsap from "gsap";
import { wedding } from "@/data/wedding";
import { InvitationContent } from "./InvitationContent";

interface EnvelopeStageProps {
  opened: boolean;
  onOpened: () => void;
  onReplay: () => void;
}

export function EnvelopeStage({
  opened,
  onOpened,
  onReplay
}: EnvelopeStageProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [animating, setAnimating] = useState(false);

  useLayoutEffect(() => {
    if (!opened || !rootRef.current) return;
    gsap.set(rootRef.current.querySelector(".envelope-wrap"), {
      opacity: 0,
      pointerEvents: "none"
    });
  }, [opened]);

  const openEnvelope = () => {
    if (animating || opened || !rootRef.current) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      onOpened();
      return;
    }

    setAnimating(true);
    const root = rootRef.current;

    gsap.timeline({
      defaults: { overwrite: "auto" },
      onComplete: () => {
        setAnimating(false);
        onOpened();
      }
    })
      .to(root.querySelector(".wax-seal"), {
        scale: 1.1,
        duration: 0.16,
        ease: "power1.out"
      })
      .to(root.querySelector(".wax-seal"), {
        scale: 0.7,
        opacity: 0,
        duration: 0.24,
        ease: "power2.in"
      })
      .to(root.querySelector(".envelope-flap"), {
        rotateX: -180,
        duration: 0.75,
        transformOrigin: "top center",
        ease: "power2.inOut"
      }, "-=0.06")
      .to(root.querySelector(".invite-card"), {
        yPercent: -72,
        duration: 0.85,
        ease: "power3.out"
      })
      .to(root.querySelector(".envelope-body"), {
        y: 84,
        opacity: 0,
        duration: 0.55,
        ease: "power2.in"
      }, "-=0.25")
      .to(root.querySelector(".invite-card"), {
        yPercent: -120,
        scale: 1.06,
        opacity: 0,
        duration: 0.55,
        ease: "power2.inOut"
      }, "-=0.1")
      .to(root.querySelector(".envelope-wrap"), {
        opacity: 0,
        duration: 0.3
      }, "-=0.25");
  };

  return (
    <div ref={rootRef} className={`envelope-stage ${opened ? "content-open" : ""}`}>
      {!opened && <div className="ambient-glow" aria-hidden="true" />}

      {!opened && (
        <section className="envelope-wrap" aria-label="Wedding invitation envelope">
          <button
            className="envelope-button"
            type="button"
            onClick={openEnvelope}
            disabled={animating}
            aria-label="Open wedding invitation"
          >
            <span className="envelope-scene">
              <span className="invite-card">
                <span className="mini-symbol">
                  <Image src="/kodava-symbol.svg" alt="" width={46} height={46} />
                </span>
                <span className="mini-copy">Wedding Invitation</span>
                <span className="mini-names">
                  {wedding.couple.bride.name} &amp; {wedding.couple.groom.name}
                </span>
              </span>

              <span className="envelope-body">
                <span className="envelope-back" />
                <span className="envelope-left" />
                <span className="envelope-right" />
                <span className="envelope-bottom" />
                <span className="envelope-flap" />
                <span className="wax-seal" aria-hidden="true">K</span>
              </span>
            </span>
          </button>

          <div className="open-hint">
            <span>Tap to open</span>
            <span className="hint-line" aria-hidden="true" />
          </div>
        </section>
      )}

      {opened && <InvitationContent onReplay={onReplay} />}
    </div>
  );
}
