"use client";

import { useEffect, useState } from "react";
import { EnvelopeStage } from "./EnvelopeStage";
import { SplashScreen } from "./SplashScreen";

type Stage = "splash" | "envelope" | "invitation";

export function WeddingExperience() {
  const [stage, setStage] = useState<Stage>("splash");

  useEffect(() => {
    const alreadyOpened = sessionStorage.getItem("wedding-invitation-opened");

    if (alreadyOpened === "true") {
      setStage("invitation");
      return;
    }

    const timer = window.setTimeout(() => setStage("envelope"), 3000);
    return () => window.clearTimeout(timer);
  }, []);

  const handleOpened = () => {
    sessionStorage.setItem("wedding-invitation-opened", "true");
    setStage("invitation");
  };

  const replay = () => {
    sessionStorage.removeItem("wedding-invitation-opened");
    setStage("envelope");
  };

  return (
    <main className="wedding-shell">
      {stage === "splash" && <SplashScreen />}

      {(stage === "envelope" || stage === "invitation") && (
        <EnvelopeStage
          opened={stage === "invitation"}
          onOpened={handleOpened}
          onReplay={replay}
        />
      )}
    </main>
  );
}
